73: function xpForNextLevel(level) { return 100 + (level - 1) * 25 }
74: function levelInfo(total = game.xp) {
75:   let level = 1, remaining = Math.max(0, Math.floor(total))
76:   while (remaining >= xpForNextLevel(level)) { remaining -= xpForNextLevel(level); level++ }
77:   return { level, current: remaining, needed: xpForNextLevel(level), percent: Math.min(100, remaining / xpForNextLevel(level) * 100) }
78: }
79: function awardXP(amount, reason, claimKey = null) {
80:   if (claimKey && game.xpClaims.includes(claimKey)) return false
81:   const reward = Math.max(0, Math.floor(Number(amount) || 0))
82:   if (!reward) return false
83:   if (claimKey) game.xpClaims.push(claimKey)
84:   game.xp += reward
85:   return true
86: }
