220: function contractProgress(contract, genome) {
221:   const ratios = contract.goals.map(([key, target]) => Math.min(1, ((genome?.[key] || [0.5, 0.5]).reduce((sum, allele) => sum + Number(allele || 0), 0) / 2) / target))
222:   const percent = Math.round(ratios.reduce((sum, ratio) => sum + ratio, 0) / ratios.length * 100)
223:   return { percent, complete: ratios.every(ratio => ratio >= 1) }
224: }
